import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/USB%E5%85%85%E9%9B%BB%E5%99%A8.html","title":"USB充電器","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.86,"words":557},"filePathRelative":"USB充電器.md"}`),a={name:`USB充電器.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="usb充電器" tabindex="-1"><a class="header-anchor" href="#usb充電器"><span>USB充電器</span></a></h1><p><a href="./グッズ関連.html">グッズ関連</a></p><p><a href="./ノートPC用電源.html">ノートPC用電源</a>もUSB充電器だが、ノートPCの備品のつもりで買っていたのでちょっと気分が違ったのでページが分かれてしまった。</p><ul><li><a href="https://en.wikipedia.org/wiki/Quick_Charge" target="_blank" rel="noopener noreferrer">Quick Charge - Wikipedia</a></li></ul><h2 id="エレコム-mpa-acd03シリーズ-合計最大60w-usb-a×6-2026-11-08-日" tabindex="-1"><a class="header-anchor" href="#エレコム-mpa-acd03シリーズ-合計最大60w-usb-a×6-2026-11-08-日"><span>エレコム MPA-ACD03シリーズ 合計最大60W USB-A×6 2026-11-08 (日)</span></a></h2><p><a href="https://www.yodobashi.com/product-detail/100000001004215107/" target="_blank" rel="noopener noreferrer">ヨドバシ.com - エレコム ELECOM USB AC充電器 MPA-ACD03シリーズ 合計最大60W USB-A×6 おまかせ充電対応 電源ケーブル付き（1.5m） ブラック MPA-ACD03BK</a></p><p>使ってた4ポート5.4Aの充電器でタブレットを充電していると、なんか満充電のあとに画面がつくようになって、満充電の処理がおかしくなっているのではないか？と思いヨドバシで適当に調べた充電器を購入することに。</p><p>2560円で購入。6ポートで60Wの割にはなんか安いがエレコムなのでそんな変なものでもないだろう、ということで。</p><p>届いた。思ったより電源ケーブルがゴツくて長くて邪魔。ただポート数は多いので、そこは良い。 満充電でおかしい挙動は無くなったので、やはり元の充電器は寿命っぽいな。</p><h2 id="cio-novaport-duoii-65w-usb-c-2ポート-2025-11-29-土" tabindex="-1"><a class="header-anchor" href="#cio-novaport-duoii-65w-usb-c-2ポート-2025-11-29-土"><span>CIO NovaPort DUOⅡ 65W USB-C 2ポート 2025-11-29 (土)</span></a></h2><p><a href="https://amzn.to/4p9eEVd" target="_blank" rel="noopener noreferrer">amazon: CIO NovaPort DUOⅡ 65W USB-C 2ポート 充電器</a></p><p>UGREENのやつが<a href="./LenovoTabP12.html">LenovoTabP12</a>では30W出なかったので、もう一つくらい試してみるか、と購入したもの。 65Wと少し余裕があり、ちゃんとQC4対応が明記されているものを選んでこれに行き着く。</p><p>LenovoTabP12で30W出なくても<a href="./MacBookAir.html">MacBookAir</a>の充電器として使おう、と思っている。</p><h3 id="_10wしか出なかった" tabindex="-1"><a class="header-anchor" href="#_10wしか出なかった"><span>10Wしか出なかった</span></a></h3><p><a href="./LenovoTabP12.html">LenovoTabP12</a>では10Wしか出なかった。UGREENのは20Wでているので向こうの方がマシだ…</p><h2 id="ugreen-nexode-mini-30w-pd-充電器-usb-c-急速充電器-2025-10-14-火" tabindex="-1"><a class="header-anchor" href="#ugreen-nexode-mini-30w-pd-充電器-usb-c-急速充電器-2025-10-14-火"><span>UGREEN Nexode Mini 30W PD 充電器 USB-C 急速充電器 2025-10-14 (火)</span></a></h2><ul><li><a href="https://amzn.to/4nnfyvD" target="_blank" rel="noopener noreferrer">amazon: UGREEN Nexode Mini 30W PD 充電器 USB-C 急速充電器 </a></li><li><a href="https://ugreen.jp/products/nexode-mini-30w-gan-fast-charger-white" target="_blank" rel="noopener noreferrer">UGREEN Nexode Mini 30W GaN 急速充電器 白</a></li></ul><p>1881円で購入。</p><p>下のRISUKAIのがQC4に対応してなくて<a href="./LenovoTabP12.html">LenovoTabP12</a>で10Wしか出ていなかったので購入。 こちらが30W出ているかは良くわからないが、40%くらいから充電しても40分とか表示されていたので結構早く充電は出来てそう。</p><p>1ポートでコンパクトなタイプ。口はC。悪くなさそうな気はしている。</p><p>UGREENって初めて購入してみたが、レビューは悪くないし、製品の印象も悪くなさそう。 ただ公式サイトにpdfのマニュアルが無いな。</p><h3 id="表示は早いが実測は早くない-2025-10-18-土" tabindex="-1"><a class="header-anchor" href="#表示は早いが実測は早くない-2025-10-18-土"><span>表示は早いが実測は早くない 2025-10-18 (土)</span></a></h3><p>しばらくいろいろ試していたが、Tab P12のSetupのバッテリーの所には「残り40分」とか出るのだが、 40分経ってもあまり進んでいない。なんか表示と実際に掛かる時間がずれているな。</p><p>充電自体はされているのだが。</p><p>30%くらいから2時間ほど充電してみたが66%。どうも電力量制御で途中からゆっくり充電になってしまっている気がする。</p><h3 id="_17wくらいしか出てない-2025-10-24-金" tabindex="-1"><a class="header-anchor" href="#_17wくらいしか出てない-2025-10-24-金"><span>17Wくらいしか出てない 2025-10-24 (金)</span></a></h3><p><a href="./USBチェッカー.html">USBチェッカー</a>を買ったのでいろいろ試しているが、今の所18Wが最高記録で、30Wは出ない。 そしてこの前買ったケーブルでは8Wしか出ない…</p><p>付属の充電器（こちらは20Wという事になっている）とだいたい同じくらいしか出ていないなぁ。 9V 2AなのでQC 2として動いているって事か？（表示はPD 2.0となっているが）</p><p>とりあえずケーブルを買って再チャレンジの予定。 どのみち今18W出ているケーブルはノートPC用に買った長いもので取り回しが悪いのだけなので、 どちらにせよUSBケーブルは必要ではあるので。</p><h2 id="risukai-pd30w-3ポート充電器-2025-10-04-土" tabindex="-1"><a class="header-anchor" href="#risukai-pd30w-3ポート充電器-2025-10-04-土"><span>RISUKAI PD30W 3ポート充電器 2025-10-04 (土)</span></a></h2><p>以下を購入した。</p><p><a href="https://hb.afl.rakuten.co.jp/ichiba/4d01a094.b11286ef.4d01a095.00be98ba/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fauc-risukai%2Ft373-%2F&amp;link_type=pict&amp;ut=eyJwYWdlIjoiaXRlbSIsInR5cGUiOiJwaWN0Iiwic2l6ZSI6IjI0MHgyNDAiLCJuYW0iOjEsIm5hbXAiOiJyaWdodCIsImNvbSI6MSwiY29tcCI6ImRvd24iLCJwcmljZSI6MCwiYm9yIjoxLCJjb2wiOjEsImJidG4iOjEsInByb2QiOjAsImFtcCI6ZmFsc2V9" target="_blank" rel="nofollow sponsored noopener" style="word-wrap:break-word;"><img src="https://hbb.afl.rakuten.co.jp/hgb/4d01a094.b11286ef.4d01a095.00be98ba/?me_id=1303095&amp;item_id=10261032&amp;pc=https%3A%2F%2Fthumbnail.image.rakuten.co.jp%2F%400_mall%2Fauc-risukai%2Fcabinet%2Fk35%2Fimgrc0107425252.jpg%3F_ex%3D240x240&amp;s=240x240&amp;t=pict" border="0" style="margin:2px;" alt="" title=""><br> RISUKAI PD30W 3ポート充電器+USB-Cケーブル</a></p><p>USBケーブルつきのを1580円で購入。30W用のケーブルはそんな無くて、200円くらいだったので。</p><p>なんか知らないブランドでどうなのかな？とも思ったが、それなりに実測値を出している人はだいたい公称値を報告しているので、 少なくとも買ったときは動いてそう。 ハズレもあるっぽいが、それは返品で対応してくれるだろうし、ちょうど<a href="./LenovoTabP12.html">LenovoTabP12</a>の充電をいろいろ調べたいので、 W表示は便利だな、とも思い購入。</p><p>届いたので試しているが、<a href="./LenovoTabP12.html">LenovoTabP12</a>は7Wくらいまでしか行かない。なんでだ？とりあえず30%くらいまで減った状態で試してみたが変わらず。 たまに10Wくらい行く事もあるが、30W行った事は無い。うーん。</p><p>なんかLenovo Tab P12はquick chargeというプロトコル対応なのか。これってPDとは違うのかしら？</p>`,36)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};